from flask import Flask, Blueprint, request, jsonify

# 1. Blueprint Modularization (Separating features into independent modules)
users_bp = Blueprint("users", __name__, url_prefix="/api/v1/users")

# In-Memory Database Store
DATABASE = {
    101: {"id": 101, "username": "hesamp", "email": "hesam@domain.com"}
}

# 2. RESTful Route Handlers
@users_bp.route("", methods=["GET"])
def list_users():
    return jsonify({"users": list(DATABASE.values()), "count": len(DATABASE)}), 200

@users_bp.route("/<int:user_id>", methods=["GET"])
def get_user(user_id: int):
    user = DATABASE.get(user_id)
    if not user:
        return jsonify({"error": "NOT_FOUND", "message": f"User #{user_id} not found."}), 404
    return jsonify(user), 200

@users_bp.route("", methods=["POST"])
def create_user():
    payload = request.get_json()
    if not payload or "username" not in payload or "email" not in payload:
        return jsonify({"error": "BAD_REQUEST", "message": "Missing username or email."}), 400

    new_id = max(DATABASE.keys(), default=100) + 1
    new_user = {"id": new_id, "username": payload["username"], "email": payload["email"]}
    DATABASE[new_id] = new_user
    return jsonify(new_user), 201  # 201 Created!

# 3. Application Factory Pattern
def create_app(config_override=None):
    app = Flask(__name__)
    app.register_blueprint(users_bp)
    return app

import unittest

# 1. Subclassing unittest.TestCase
class TestCalculator(unittest.TestCase):

    # Lifecycle Setup: Runs BEFORE EVERY test method!
    def setUp(self):
        self.base_multiplier = 2

    # Lifecycle Teardown: Runs AFTER EVERY test method!
    def tearDown(self):
        pass

    # 2. Test Methods (MUST start with 'test_')
    def test_multiplication(self):
        result = 5 * self.base_multiplier
        self.assertEqual(result, 10, "5 * 2 should equal 10")

    # 3. Floating-Point Comparison (Overcomes IEEE 754 precision issues!)
    def test_float_addition(self):
        # self.assertEqual(0.1 + 0.2, 0.3) -> FAILS due to 0.30000000000000004!
        self.assertAlmostEqual(0.1 + 0.2, 0.3, places=7)

    # 4. Testing Exceptions with Context Managers
    def test_zero_division_raises_error(self):
        with self.assertRaises(ZeroDivisionError):
            _ = 10 / 0

    # 5. Table-Driven Parameterized Subtests (self.subTest)
    def test_even_numbers(self):
        test_cases = [2, 4, 6, 8, 10]
        for num in test_cases:
            with self.subTest(num=num):
